<?php
declare(strict_types=1);
if(getenv('XAR_TEST_MYSQL_ALLOW_LOCAL')!=='1'){echo "MySQL Esprit migration skipped: explicit local opt-in required.\n";exit(0);}
$dsn=(string)getenv('XAR_TEST_MYSQL_DSN');if(preg_match('/^mysql:host=127\.0\.0\.1;port=([1-9][0-9]{3,4});charset=utf8mb4$/D',$dsn,$parts)!==1||(int)$parts[1]>65535)throw new RuntimeException('Loopback fixture required.');
require_once __DIR__.'/../api/v1/domains.php';require_once __DIR__.'/../api/v1/online.php';
function spiritCheck(bool $value,string $message):void{if(!$value)throw new RuntimeException($message);echo 'PASS '.$message.PHP_EOL;}
$schema='regie_spirit_audit_'.bin2hex(random_bytes(8));$db=new PDO($dsn,(string)getenv('XAR_TEST_MYSQL_USER'),(string)getenv('XAR_TEST_MYSQL_PASSWORD'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
try{
 $db->exec('CREATE DATABASE `'.$schema.'` CHARACTER SET utf8mb4');$db->exec('USE `'.$schema.'`');
 $db->exec('CREATE TABLE schema_migrations(version INT PRIMARY KEY,name VARCHAR(100),checksum VARCHAR(64)) ENGINE=InnoDB');$db->exec("INSERT INTO schema_migrations VALUES(23,'previous','unchanged')");
 $db->exec('CREATE TABLE application_domain_clock(singleton_id INT PRIMARY KEY,global_revision BIGINT,state_schema_version INT,domain_schema_version INT,legacy_revision BIGINT NULL,initialized_at DATETIME(3)) ENGINE=InnoDB');
 $db->exec('CREATE TABLE application_domains(domain_key VARCHAR(200) PRIMARY KEY,schema_version INT,revision BIGINT,payload JSON,updated_by_account_id VARCHAR(128) NULL,updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3)) ENGINE=InnoDB');
 $db->exec('CREATE TABLE application_domain_history(history_id BIGINT AUTO_INCREMENT PRIMARY KEY,domain_key VARCHAR(200),domain_revision BIGINT,global_revision BIGINT,operation VARCHAR(10),payload JSON,changed_by_account_id VARCHAR(128) NULL) ENGINE=InnoDB');
 $db->exec('CREATE TABLE application_domain_changes(global_revision BIGINT,domain_key VARCHAR(200),domain_revision BIGINT,operation VARCHAR(10),PRIMARY KEY(global_revision,domain_key)) ENGINE=InnoDB');
 $db->exec("INSERT INTO application_domain_clock VALUES(1,100,22,1,8,UTC_TIMESTAMP(3))");
 $character=['id'=>'synthetic','name'=>'Personnage entièrement fictif','characterSchemaVersion'=>9,'stats'=>['force'=>45,'spiritSocial'=>0,'intelligence'=>61],'resources'=>['hp'=>17,'maxHp'=>90,'mana'=>12.5],'fatigue'=>['current'=>73,'max'=>150],'inventory'=>'Ne pas effacer cette note','abilities'=>[['id'=>'custom','castingStatId'=>'character-stat-spiritSocial']],'private'=>['arbitrary'=>'preserved']];
 $token=['id'=>'synthetic-clone','followCharacter'=>false,'stats'=>[['id'=>'character-stat-spiritSocial','label'=>'Esprit / Social','value'=>'82'],['id'=>'character-stat-intelligence','label'=>'Intelligence','value'=>'41']],'hp'=>5,'mana'=>7.5,'weaponAttacks'=>[['id'=>'claws','formula'=>'1d6','damageType'=>'physical']]];
 $docs=['character:synthetic'=>$character,'token:synthetic-scene:synthetic-clone'=>$token,'library'=>['tokenLibrary'=>[$token]],'activity'=>['rolls'=>[['statId'=>'character-stat-spiritSocial','label'=>'Esprit / Social','total'=>11]]],'items'=>['version'=>1,'templates'=>[],'instances'=>[]]];
 $insert=$db->prepare('INSERT INTO application_domains(domain_key,schema_version,revision,payload)VALUES(?,1,11,?)');foreach($docs as$key=>$payload)$insert->execute([$key,json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);
 $snapshot=static fn()=>[$db->query('SELECT * FROM application_domains ORDER BY domain_key')->fetchAll(),$db->query('SELECT * FROM application_domain_history ORDER BY history_id')->fetchAll(),$db->query('SELECT * FROM application_domain_changes ORDER BY global_revision,domain_key')->fetchAll(),$db->query('SELECT * FROM application_domain_clock')->fetchAll(),$db->query('SELECT * FROM schema_migrations ORDER BY version')->fetchAll()];
 $before=$snapshot();$db->exec("CREATE TRIGGER fail_spirit BEFORE UPDATE ON application_domains FOR EACH ROW BEGIN IF NEW.domain_key LIKE 'token:%' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic_mid_migration_failure'; END IF; END");
 try{migrateApplicationSpiritStatistics($db);spiritCheck(false,'Injected failure must abort');}catch(PDOException $e){spiritCheck(str_contains($e->getMessage(),'synthetic_mid_migration_failure'),'Failure injected after earlier writes');}
 spiritCheck($snapshot()===$before,'Failure rolls back payloads, history, revisions, clock and schema marker together');$db->exec('DROP TRIGGER fail_spirit');
 spiritCheck(migrateApplicationSpiritStatistics($db)===3,'Only character, independent clone and library migrate');
 $read=static fn($key)=>json_decode($db->query('SELECT payload FROM application_domains WHERE domain_key='.$db->quote($key))->fetchColumn(),true,512,JSON_THROW_ON_ERROR);
 $actual=$read('character:synthetic');spiritCheck($actual['stats']['spirit']===30&&$actual['stats']['spiritSocial']===0,'Esprit defaults to 30 without replacing zero Social');$expected=$character;$expected['characterSchemaVersion']=10;$expected['stats']=applicationCharacterStats($character['stats']);spiritCheck($actual===$expected,'All character resources, skills and private extensions remain exactly identical');
 spiritCheck($read('token:synthetic-scene:synthetic-clone')['stats']===applicationUnitStatRows($token['stats']),'Clone gets its own new score, without changing mana, HP or attacks');
 spiritCheck($read('activity')===$docs['activity']&&$read('items')===$docs['items'],'Historical results and stock are untouched');
 $history=json_decode($db->query("SELECT payload FROM application_domain_history WHERE domain_key='character:synthetic'")->fetchColumn(),true,512,JSON_THROW_ON_ERROR);spiritCheck($history===$character,'Backup contains the raw original, before normalization');
 spiritCheck((int)$db->query('SELECT global_revision FROM application_domain_clock')->fetchColumn()===101,'One atomic global revision');$after=$snapshot();spiritCheck(migrateApplicationSpiritStatistics($db)===0&&$snapshot()===$after,'Repeat migration changes no bytes, duration or stock');
 $db->exec('DELETE FROM schema_migrations WHERE version=24');$db->exec("UPDATE application_domains SET payload=JSON_SET(payload,'$.characterSchemaVersion',11) WHERE domain_key='character:synthetic'");$before=$snapshot();try{migrateApplicationSpiritStatistics($db);spiritCheck(false,'Future character accepted');}catch(RuntimeException $e){spiritCheck($e->getMessage()==='future_character_schema','Future character refused');}spiritCheck($snapshot()===$before,'Future schema refusal writes nothing');
 echo "Local MySQL Esprit migration integration passed.\n";
}finally{if(preg_match('/^regie_spirit_audit_[a-f0-9]{16}$/D',$schema)!==1)throw new RuntimeException('Unsafe cleanup');$db->exec('DROP DATABASE IF EXISTS `'.$schema.'`');}
